using System;using System.IO;using System.Linq;using System.Reflection;using System.Threading.Tasks;using System.Collections.Generic;using UnityEngine;using AntColony.Units;using AntColony.Core;
public static class Final1113WorkProfiles{
 [Serializable]public class Profile{public string action;public Vector3[] points;}
 [Serializable]public class Data{public Profile[] profiles;}
 static Vector3[] Read(Mesh mesh){using(var data=UnityEditor.MeshUtility.AcquireReadOnlyMeshData(mesh)){using(var vertices=new Unity.Collections.NativeArray<Vector3>(data[0].vertexCount,Unity.Collections.Allocator.Temp)){data[0].GetVertices(vertices);return vertices.ToArray();}}} public static async Task<string> Run(){AntColony.UI.SimulationPause.UserSpeed(0);var c=CommanderRoster.Instance.Commanders.First(x=>x&&x.IsColonyMember);var v=c.GetComponent<AntVisual>();var p=c.GetComponent<MeshyNativeMotionPlayer>();var lib=Resources.Load<MeshyNativeLibrary>("MeshyNative/Runtime");var flags=BindingFlags.Instance|BindingFlags.NonPublic;var motion=typeof(AntVisual).GetField("playedClip",flags);var held=typeof(AntVisual).GetField("heldTool",flags);var oldMotion=motion.GetValue(v);var oldTool=held.GetValue(v);string oldPreview=p.PreviewMotion;float oldPhase=p.PreviewPhase;var profiles=new List<Profile>();try{
 foreach(var pair in new[]{("Tool_Mine","Tool_Pickaxe_Stone"),("Tool_Chop","Tool_Axe_Stone"),("Tool_Dig","Tool_Shovel_Stone"),("Tool_Till","Tool_Hoe_Stone"),("Tool_Hammer","Tool_Hammer_Stone")}){
 motion.SetValue(v,pair.Item1);held.SetValue(v,pair.Item2);p.PreviewMotion=lib.actions.First(a=>a.action==pair.Item1).motion;p.PreviewPhase=0;await Task.Delay(200);var mount=p.GetComponentsInChildren<Transform>().First(t=>t.name=="Native equipment grip"&&t.gameObject.activeInHierarchy);var item=mount.GetChild(0); if(item.GetComponentsInChildren<MeshFilter>().Length==0)throw new Exception(pair.Item1+" item="+item.name+" mountchildren="+mount.childCount+" itemActive="+item.gameObject.activeSelf);var points=item.GetComponentsInChildren<MeshFilter>().SelectMany(f=>Read(f.sharedMesh).Select(x=>mount.InverseTransformPoint(f.transform.TransformPoint(x)))).ToArray();if(points.Length==0)throw new Exception(pair.Item1+" item="+item.name+" meshes="+string.Join(",",item.GetComponentsInChildren<MeshFilter>().Select(f=>f.name+":"+f.sharedMesh.vertexCount+" read="+f.sharedMesh.isReadable+" array="+f.sharedMesh.vertices.Length)));float low=points.Min(x=>x.z),high=points.Max(x=>x.z);var head=points.Where(x=>x.z<low+(high-low)*.25f).ToArray();var tips=new[]{head.OrderBy(x=>x.x).First(),head.OrderByDescending(x=>x.x).First(),head.OrderBy(x=>x.y).First(),head.OrderByDescending(x=>x.y).First(),head.OrderBy(x=>x.z).First(),head.OrderByDescending(x=>x.z).First()}.Distinct().Select(x=>item.InverseTransformPoint(mount.TransformPoint(x))).ToArray();var sampled=new List<Vector3>();var forward=p.NativeModel.parent.forward;var right=p.NativeModel.parent.right;float floor=c.Position.y;if(Physics.Raycast(c.Position+Vector3.up*3,Vector3.down,out var ground,10,1<<8))floor=ground.point.y;
 for(int i=0;i<72;i++){p.PreviewPhase=i/72f;await Task.Delay(25);foreach(var tip in tips){var world=item.TransformPoint(tip);sampled.Add(new Vector3(Vector3.Dot(world-c.Position,right),world.y-floor,Vector3.Dot(world-c.Position,forward)));}}
 profiles.Add(new Profile{action=pair.Item1,points=sampled.ToArray()});}
 var data=Newtonsoft.Json.JsonConvert.SerializeObject(new {profiles=profiles.Select(q=>new {action=q.action,points=q.points.Select(v=>new {x=v.x,y=v.y,z=v.z})})},Newtonsoft.Json.Formatting.Indented);File.WriteAllText("work/final-motion-1113/work-contact-profiles.json",data);return string.Join("\n",profiles.Select(x=>x.action+" samples="+x.points.Length+" y="+x.points.Min(v=>v.y)+".."+x.points.Max(v=>v.y)));}
 finally{motion.SetValue(v,oldMotion);held.SetValue(v,oldTool);p.PreviewMotion=oldPreview;p.PreviewPhase=oldPhase;}}
}
